TASK: 同时完成 Innovation Classification 与 CIE Scoring。
允许类别：["Conventional", "Surface Innovation", "Incremental Innovation", "Structural Innovation", "Transformative Innovation", "Adversarial Trap"]
OUTPUT SCHEMA:
{"category": "one controlled category", "scores": {"culinary_knowledge_grounding": 1, "existing_culinary_precedent_analysis": 1, "innovation_delta_quality": 1, "mechanistic_plausibility": 1, "innovation_value": 1, "realization_quality": 1}, "reasoning": "<=180 Chinese characters", "failure_modes": []}
CASE:
{"id": "CIE-002", "culinary_context": {"traditional_reference": [{"name": "闽南/潮汕海鲜炒米粉", "core_principle": "以海鲜高汤润粉、猛火收汁并追求镬气"}, {"name": "蟹粉/蟹膏拌面饭", "core_principle": "把甲壳类鲜味和脂香集中到主食载体"}], "innovation_space": ["ingredient stacking", "flavor architecture", "cooking technique"]}, "dish_information": {"name": "五种海蟹炒米粉（蟹蟹你的爱）", "description": "以多种海蟹拆肉、熬汤并与米粉合炒，目标是让米粉吸收蟹汤、蟹膏与炒制香气。创作者公开材料称其招牌为‘五种海蟹炒米粉’，节目切片强调蟹肉与镬气；具体五种蟹的品种未在可访问文字资料中完整列明，因此本数据不补造品种。[CIE002-S1][CIE002-S2]", "ingredients": [{"name": "多种海蟹", "culinary_role": "鲜味来源与卖点", "physical_property": "蟹肉细嫩、易失水；蟹膏富脂，风味浓但易腥"}, {"name": "米粉", "culinary_role": "吸汁与承味主体", "physical_property": "多孔淀粉网络，回软后易吸汤，也易断、黏或糊"}, {"name": "蟹汤", "culinary_role": "连接蟹与米粉的风味介质", "physical_property": "含可溶性鲜味物质与胶质，浓缩后咸鲜显著"}, {"name": "香辛料/葱蒜", "culinary_role": "去腥与炒香背景", "physical_property": "挥发性强，高温能建立顶香但过量会遮蔽蟹味"}], "techniques": [{"name": "拆蟹取肉", "purpose": "剔除硬壳并保护纤维", "expected_effect": "提高可食性，减少壳渣"}, {"name": "蟹壳熬汤", "purpose": "回收壳与组织中的风味", "expected_effect": "建立浓缩海鲜底味"}, {"name": "猛火合炒与收汁", "purpose": "让米粉吸收汤汁并产生炒香", "expected_effect": "粉体干爽而着味，形成镬气"}]}, "innovation_trace": {"existing_culinary_context": {"precedents": ["海鲜炒米粉", "蟹粉拌面", "甲壳熬汤后回灌主食"], "relationship": "结构本身成熟：海鲜提供鲜味，汤汁把风味迁移到淀粉，猛火收汁控制干湿。所谓创新主要来自把多个蟹种并列，而不是创建新角色或新技术。"}, "ingredient_and_technique_knowledge": {"ingredient_knowledge": [{"ingredient": "蟹肉与蟹膏", "property": "呈味核苷酸、氨基酸与脂溶性香气共同形成甜鲜和膏香；不同蟹的差异必须可感知才有叠加价值"}, {"ingredient": "米粉", "property": "吸液能力使其适合承接浓汤，但过度翻炒或水量过大会断裂、发黏"}], "technique_knowledge": [{"technique": "壳熬汤", "principle": "通过热水萃取和浓缩回收鲜味；烘烤/炒香壳可增加焦香，但也可能引入苦腥"}, {"technique": "镬炒收汁", "principle": "高热与快速翻动兼顾蒸发和表面香气，窗口很窄"}]}, "innovation_delta": {"before": "传统海蟹炒米粉通常使用一种主蟹或一组海鲜，以蟹汤和镬气完成风味。", "after": "同时使用五种海蟹，并把‘品种数量’作为主体叙事与高级感来源。", "change_type": ["ingredient stacking"], "magnitude": 2}, "mechanistic_justification": {"flavor_mechanism": "蟹汤与蟹膏对米粉有明确增鲜机制；但若五种蟹的风味在熬汤和合炒后趋同，增加品种只提高成本和叙事复杂度，不提高可辨识层次。", "texture_mechanism": "拆出的蟹肉提供纤维感，米粉应保持分离和弹性；汤量、油量与火力失衡会导致粉黏、蟹肉柴。", "chemical_or_culinary_basis": "‘蟹+汤+米粉’机制强，‘五种比一种更创新’机制弱。评价应把菜好吃与创新增量分开。", "strength": "medium"}, "creative_hypothesis": "通过多蟹种的甜鲜、膏香和纤维差异，构建比单一海蟹更宽的海味谱系，并由米粉统一承载。", "risk_and_constraint": {"risk": "多蟹风味互相平均化；蟹膏过重产生腥腻；品种数量成为不可盲辨的奢华堆叠。", "tradeoff": "理论风味宽度增加，同时原料成本、拆解劳动与批次稳定性显著上升。", "failure_condition": "盲尝无法区分多蟹与单蟹高汤版本，或增加蟹种后只有鲜度更重而无清晰层次。"}}}

